CREATE TABLE IF NOT EXISTS invitations (id SERIAL PRIMARY KEY,organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,email VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'agent',token_hash VARCHAR(128) UNIQUE NOT NULL,invited_by INTEGER REFERENCES users(id),accepted_at TIMESTAMP,expires_at TIMESTAMP NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS model_versions (id SERIAL PRIMARY KEY,version VARCHAR(80) UNIQUE NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',metrics_json TEXT,artifact_path VARCHAR(255),created_at TIMESTAMP NOT NULL DEFAULT NOW());
